// RULES.: Cloudflare Worker + D1. Оплата и доставка подтверждаются продавцом вручную.
const sendJson=(data,status=200,headers={})=>Response.json(data,{status,headers:{'cache-control':'no-store',...headers}});
const COST_ORDERS_QUERY="SELECT o.id order_id,o.created_at date_utc,o.total net_paid_goods_rub,\n COALESCE((SELECT SUM(c.qty*c.unit_cost) FROM bx_order_cost_lines c WHERE c.order_id=o.id),0) cost_rub,\n CASE WHEN EXISTS(SELECT 1 FROM order_items i WHERE i.order_id=o.id)\n AND NOT EXISTS(SELECT 1 FROM bx_order_cost_lines c WHERE c.order_id=o.id AND c.unit_cost IS NULL)\n AND NOT EXISTS(SELECT 1 FROM order_items i WHERE i.order_id=o.id AND NOT EXISTS(SELECT 1 FROM bx_order_cost_lines c WHERE c.order_id=o.id AND c.kind='sold' AND c.source_key=CAST(i.id AS TEXT) AND c.qty=i.qty AND c.unit_cost IS NOT NULL))\n AND NOT EXISTS(SELECT 1 FROM bx_order_gifts g WHERE g.order_id=o.id AND g.product_id!='' AND NOT EXISTS(SELECT 1 FROM bx_order_cost_lines c WHERE c.order_id=o.id AND c.kind='gift_product' AND c.source_key=g.product_id AND c.qty=g.qty AND c.unit_cost IS NOT NULL))\n AND NOT EXISTS(SELECT 1 FROM bx_order_gifts g WHERE g.order_id=o.id AND g.description!='' AND NOT EXISTS(SELECT 1 FROM bx_order_cost_lines c WHERE c.order_id=o.id AND c.kind='gift_other' AND c.source_key='description' AND c.unit_cost IS NOT NULL))\n THEN 1 ELSE 0 END cost_complete\n FROM orders o WHERE o.created_at>=? AND o.created_at<datetime(?,'+1 day') AND o.status='delivered' AND o.payment_status='paid' ";
function cors(req,env){try{let origin=new URL(env.SITE_URL).origin;if(req.headers.get('Origin')===origin)return {'access-control-allow-origin':origin,'vary':'Origin','access-control-allow-methods':'GET, POST, OPTIONS','access-control-allow-headers':'content-type, authorization'}}catch{}return {}}
async function tg(token,method,data){const r=await fetch('https://api.telegram.org/bot'+token+'/'+method,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok||!d.ok)throw Error('Telegram '+String(d.error_code||r.status)+': '+String(d.description||'ошибка отправки').slice(0,140));return d.result}
const clip=(x,n)=>typeof x==='string'?x.trim().slice(0,n):'';
async function notify(env,id){
 if(!env.OWNER_BOT_TOKEN||!env.OWNER_CHAT_ID)return;
 const row=await env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(id).first();if(!row)return;
 const items=(await env.DB.prepare('SELECT name,price,qty FROM order_items WHERE order_id=?').bind(id).all()).results;
 const gift=await env.DB.prepare('SELECT product_name,qty,description FROM bx_order_gifts WHERE order_id=?').bind(id).first();const sale=await env.DB.prepare('SELECT COALESCE(SUM((base_price-sale_price)*qty),0) AS discount FROM bx_order_sale_lines WHERE order_id=?').bind(id).first();const shipping=await env.DB.prepare('SELECT free_shipping FROM bx_order_shipping_benefits WHERE order_id=?').bind(id).first();const names={pickup:'Самовывоз, Москва (м. Крылатское)',courier:'Курьер, Москва и область',cdek:'СДЭК'};const estimate=await readRulesQuote(env,id);const contact=await env.DB.prepare('SELECT email,requested_zone FROM rules_order_contact_delivery WHERE order_id=?').bind(id).first();
 let text='🛒 RULES. — новый заказ\n№ '+row.id+'\n\n'+items.map(x=>`${x.name} × ${x.qty} — ${x.price*x.qty} ₽`).join('\n')+(sale?.discount?'\n\nКлубная скидка: −'+sale.discount+' ₽':'')+(gift?'\n\n🎁 Подарок: '+[gift.product_name?gift.product_name+' × '+gift.qty:'',gift.description].filter(Boolean).join(' · '):'')+'\n\nТовары: '+row.total+' ₽\nДоставка: '+(shipping?.free_shipping?'БЕСПЛАТНО по промокоду (не добавлять стоимость)':estimate?.state==='estimated'?'предварительно '+estimate.quotedRub+' ₽, требуется подтверждение':estimate?.state==='estimated_free'?'предварительно бесплатно по порогу, требуется подтверждение':estimate?.state==='pickup'?'самовывоз, 0 ₽':'стоимость уточняется')+'\nПолучение: '+names[row.delivery]+'\nОплата: '+({cash:'при получении — по согласованию',sbp:'СБП, не подтверждена',card:'банковская карта, не подтверждена'}[row.payment]||'уточняется')+'\nИмя: '+row.customer_name+'\nТелефон: '+row.phone+'\nE-mail: '+(contact?.email||'не указан')+'\nЗаявленная зона: '+({moscow:'Москва',oblast:'Московская область'}[contact?.requested_zone]||'не указана')+'\nГород: '+row.city+'\nАдрес/ПВЗ: '+row.address+'\nКомментарий: '+row.comment;
 try{await tg(env.OWNER_BOT_TOKEN,'sendMessage',{chat_id:env.OWNER_CHAT_ID,text});await env.DB.prepare("UPDATE outbox SET state='sent', attempts=attempts+1,last_error='' WHERE order_id=?").bind(id).run()}
 catch{await env.DB.prepare("UPDATE outbox SET attempts=attempts+1,last_error='telegram_error' WHERE order_id=?").bind(id).run()}
}
// Provisional quote only; matching a city name is not delivery-zone verification.
function rulesShippingQuote(method,city,merchandiseAfterDiscounts,freePromo,settings,requestedZone){
 if(method==='courier'&&requestedZone==='oblast')return {state:'zone_to_be_confirmed',quotedRub:null};
 if(freePromo)return {state:'free_by_promo',quotedRub:0};
 if(method==='pickup')return {state:'pickup',quotedRub:0};
 if(method==='cdek')return {state:'to_be_confirmed',quotedRub:null};
 if(city.trim().toLowerCase()!=='москва')return {state:'zone_to_be_confirmed',quotedRub:null};
 return merchandiseAfterDiscounts>=settings.free_from?{state:'estimated_free',quotedRub:0}:{state:'estimated',quotedRub:settings.courier_price};
}
async function readRulesQuote(env,id){const q=await env.DB.prepare('SELECT state,quoted_rub,merchandise_after_discounts FROM rules_delivery_quotes WHERE order_id=?').bind(id).first();return q?{state:q.state,quotedRub:q.quoted_rub,merchandiseAfterDiscounts:q.merchandise_after_discounts,provisional:true}:null}
// Invoice data is built exclusively from saved order data, never from a client-supplied total.
async function buildInvoice(env,id){
 const o=await env.DB.prepare('SELECT id,created_at,customer_name,phone,city,address,delivery,payment,status,payment_status,total FROM orders WHERE id=?').bind(id).first();if(!o)return {error:'Заказ не найден',status:404};
 if(o.status==='cancelled')return {error:'Заказ отменён; счёт недоступен',status:409};if(o.payment_status==='paid')return {error:'Оплата уже подтверждена',status:409};
 const existing=await env.DB.prepare('SELECT snapshot_json FROM rules_invoice_versions WHERE order_id=? AND revoked_at IS NULL').bind(id).first();if(existing){try{return {invoice:JSON.parse(existing.snapshot_json)}}catch{return {error:'Данные сохранённого счёта повреждены',status:500}}}
 const f=await env.DB.prepare('SELECT gross,discount,points_used FROM bx_order_finance WHERE order_id=?').bind(id).first();
 const rows=(await env.DB.prepare('SELECT i.name,i.price,i.qty,COALESCE(s.sale_price,i.price) effective_price FROM order_items i LEFT JOIN bx_order_sale_lines s ON s.order_id=i.order_id AND s.product_id=i.product_id WHERE i.order_id=? ORDER BY i.id').bind(id).all()).results||[];
 const contact=await env.DB.prepare('SELECT email FROM rules_order_contact_delivery WHERE order_id=?').bind(id).first();if(!f||!rows.length||!contact)return {error:'Данные счёта неполные',status:409};
 const merchandise=rows.reduce((a,x)=>a+x.effective_price*x.qty,0),goods=merchandise-f.discount-f.points_used;
 if(!Number.isSafeInteger(goods)||goods<0||goods!==o.total)return {error:'Сумма заказа изменилась или не сходится',status:409};
 let delivery=0,deliveryLabel='Самовывоз',deliveryZone=null;if(o.delivery==='courier'){const d=await env.DB.prepare('SELECT zone,amount FROM rules_confirmed_delivery WHERE order_id=?').bind(id).first();if(!d)return {error:'Доставка ещё не подтверждена',status:409};delivery=d.amount;deliveryZone=d.zone;deliveryLabel=d.zone==='moscow'?'Курьер по Москве':'Курьер по Московской области'}else if(o.delivery==='cdek')deliveryLabel='СДЭК — оплачивается отдельно';else if(o.delivery!=='pickup')return {error:'Неизвестный способ доставки',status:409};
 const version=crypto.randomUUID(),invoice={id:o.id,version,issuedAt:new Date().toISOString(),createdAt:o.created_at,buyer:{name:o.customer_name,phone:o.phone,email:contact.email,city:o.city,address:o.address},items:rows.map(x=>({name:x.name,qty:x.qty,unitPrice:x.effective_price})),discount:f.discount,points:f.points_used,goodsTotal:goods,delivery,deliveryLabel,total:goods+delivery,payment:o.payment};
 const query="INSERT OR IGNORE INTO rules_invoice_versions(version_id,order_id,snapshot_json) SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM orders o WHERE o.id=? AND o.status<>'cancelled' AND o.payment_status='unpaid' AND o.total=? AND o.delivery=? AND (o.delivery<>'courier' OR EXISTS(SELECT 1 FROM rules_confirmed_delivery d WHERE d.order_id=o.id AND d.zone=? AND d.amount=?)))";
 await env.DB.prepare(query).bind(version,id,JSON.stringify(invoice),id,goods,o.delivery,deliveryZone,delivery).run();
 const saved=await env.DB.prepare('SELECT snapshot_json FROM rules_invoice_versions WHERE order_id=? AND revoked_at IS NULL').bind(id).first();if(!saved)return {error:'Данные заказа изменились. Обновите страницу.',status:409};try{return {invoice:JSON.parse(saved.snapshot_json)}}catch{return {error:'Данные сохранённого счёта повреждены',status:500}};
}
async function createOrder(req,env,ctx){
 if(!env.DB)return sendJson({error:'База не подключена'},503,cors(req,env));
 if(!env.OWNER_BOT_TOKEN||!env.OWNER_CHAT_ID)return sendJson({error:'Уведомления владельцу не настроены'},503,cors(req,env));
 let body;try{if(Number(req.headers.get('content-length')||0)>20000)throw Error();const text=await req.text();if(text.length>20000)throw Error();body=JSON.parse(text)}catch{return sendJson({error:'Некорректный запрос'},400,cors(req,env))}
 const id=clip(body.id,36), name=clip(body.name,100),phone=clip(body.phone,30),city=clip(body.city,100),address=clip(body.address,250),comment=clip(body.comment,500),delivery=body.delivery,payment=body.payment;
 if(!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)||name.length<2||phone.replace(/\D/g,'').length<10||!city||!['pickup','courier','cdek'].includes(delivery)||!['cash','sbp','card'].includes(payment)||(delivery==='courier'&&!address)||body.consent!==true||!Array.isArray(body.items)||body.items.length<1||body.items.length>30)return sendJson({error:'Проверьте поля заказа и способ оплаты'},400,cors(req,env));
 const invoiceToken=body.invoiceToken==null?'':body.invoiceToken;if(typeof invoiceToken!=='string'||(invoiceToken&&!/^[0-9a-f]{64}$/.test(invoiceToken)))return sendJson({error:'Некорректный ключ доступа к счёту'},400,cors(req,env));
 const email=typeof body.email==='string'?body.email.trim():'';const requestedZone=body.requestedZone==null||body.requestedZone===''?null:body.requestedZone;if(email.length>254||(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))||(requestedZone!==null&&!['moscow','oblast'].includes(requestedZone))||(requestedZone!==null&&delivery!=='courier'))return sendJson({error:'Проверьте электронную почту и зону доставки'},400,cors(req,env));
 const existing=await env.DB.prepare('SELECT id,total FROM orders WHERE id=?').bind(id).first();if(existing){const ship=await env.DB.prepare('SELECT free_shipping FROM bx_order_shipping_benefits WHERE order_id=?').bind(id).first();const deliveryQuote=await readRulesQuote(env,id);return sendJson({ok:true,id,duplicate:true,total:existing.total,freeShipping:!!ship?.free_shipping,deliveryQuote},200,cors(req,env))}
 const customer=await customerSession(req,env).catch(()=>null);
 if(req.headers.has('authorization')&&!customer)return sendJson({error:'Сессия истекла. Войдите в кабинет снова.'},401,cors(req,env));
 const sales=customer?await clubSalePrices(env,customer.id):[],saleMap=new Map(sales.map(x=>[x.product_id,x]));
 const seen=new Set(),items=[];
 for(const item of body.items){if(typeof item.id!=='string'||item.id.length>100||seen.has(item.id)||!Number.isInteger(item.price)||item.price<=0||!Number.isInteger(item.qty)||item.qty<1||item.qty>20)return sendJson({error:'Некорректная корзина'},400,cors(req,env));seen.add(item.id);const p=await env.DB.prepare('SELECT id,name,price,stock FROM products WHERE id=? AND active=1').bind(item.id).first();if(!p||p.stock<item.qty||!Number.isInteger(p.price)||p.price<=0||p.price!==item.price)return sendJson({error:'Товар недоступен или его остаток изменился. Обновите каталог.'},409,cors(req,env));const sale=saleMap.get(item.id),price=sale?sale.sale_price:p.price;if((item.expectedSalePrice??item.price)!==price)return sendJson({error:'Клубная цена изменилась. Обновите корзину.'},409,cors(req,env));items.push({...p,qty:item.qty,sale})}
 const total=items.reduce((a,x)=>a+x.price*x.qty,0);if(!Number.isSafeInteger(total)||total>10000000)return sendJson({error:'Недопустимая сумма'},400,cors(req,env));
 const saleTotal=items.reduce((a,x)=>a+(x.sale?.sale_price??x.price)*x.qty,0);
 let statements=[env.DB.prepare('INSERT INTO orders(id,customer_name,phone,city,address,delivery,payment,comment,total,consent) VALUES(?,?,?,?,?,?,?,?,?,1)').bind(id,name,phone,city,address,delivery,payment,comment,total)];
 const promoCode=clip(body.promo,40).toUpperCase();const points=body.points==null?0:body.points;if(!Number.isInteger(points)||points<0||points>total)return sendJson({error:'Некорректное количество баллов'},400,cors(req,env));if(points&&!customer)return sendJson({error:'Для использования баллов войдите в кабинет'},401,cors(req,env));let promoPercent=0,fixedAmount=0,promoGift=null;if(promoCode){if(!/^[A-Z0-9_-]{3,40}$/.test(promoCode))return sendJson({error:'Некорректный промокод'},400,cors(req,env));const promo=await env.DB.prepare("SELECT CASE WHEN a.code IS NULL AND n.code IS NULL THEN p.percent ELSE 0 END percent,COALESCE(a.amount,0) fixed_amount,CASE WHEN n.code IS NULL THEN 0 ELSE 1 END no_discount,COALESCE(g.product_id,'') gift_product_id,COALESCE(g.qty,0) gift_qty,COALESCE(g.description,'') gift_description,COALESCE(sh.methods,'') shipping_methods FROM bx_promos p LEFT JOIN bx_promo_amounts a ON a.code=p.code LEFT JOIN bx_promo_no_discount n ON n.code=p.code LEFT JOIN bx_promo_gifts g ON g.code=p.code LEFT JOIN bx_promo_shipping sh ON sh.code=p.code WHERE p.code=? AND p.active=1").bind(promoCode).first();if(!promo)return sendJson({error:'Промокод недействителен'},400,cors(req,env));promoPercent=promo.percent;fixedAmount=promo.fixed_amount;promoGift=promo;const signature=JSON.stringify([promo.gift_product_id,promo.gift_qty,promo.gift_description,promo.no_discount]);if(body.expectedPromoPercent!==promoPercent||Number(body.expectedPromoAmount||0)!==fixedAmount||String(body.expectedPromoGift||'')!==(signature==='["",0,"",0]'?'':signature)||String(body.expectedPromoShipping||'')!==promo.shipping_methods)return sendJson({error:'Условия акции изменились. Обновите страницу.'},409,cors(req,env))}const discount=fixedAmount?Math.min(saleTotal,fixedAmount):Math.floor(saleTotal*promoPercent/100);if(points>saleTotal-discount)return sendJson({error:'Слишком много баллов'},400,cors(req,env));
 statements.push(env.DB.prepare('INSERT INTO rules_order_contact_delivery(order_id,email,requested_zone) VALUES(?,?,?)').bind(id,email,requestedZone));
 if(invoiceToken)statements.push(env.DB.prepare("INSERT INTO rules_guest_invoice_access(order_id,token_hash,expires_at) VALUES(?,?,datetime('now','+30 days'))").bind(id,hex(await sha(invoiceToken))));
 if(customer)statements.push(env.DB.prepare('INSERT INTO bx_order_owners(order_id,customer_id) VALUES(?,?)').bind(id,customer.id));
 for(const p of items)statements.push(env.DB.prepare('INSERT INTO order_items(order_id,product_id,name,price,qty) VALUES(?,?,?,?,?)').bind(id,p.id,p.name,p.price,p.qty));
 for(const p of items)if(p.sale)statements.push(env.DB.prepare('INSERT INTO bx_order_sale_lines(order_id,product_id,level,base_price,sale_price,qty) VALUES(?,?,?,?,?,?)').bind(id,p.id,p.sale.level,p.price,p.sale.sale_price,p.qty));
 if(promoCode)statements.push(env.DB.prepare('INSERT INTO bx_promo_expectations(order_id,code,product_id,qty,description,no_discount) VALUES(?,?,?,?,?,?)').bind(id,promoCode,promoGift.gift_product_id,promoGift.gift_qty,promoGift.gift_description,promoGift.no_discount));
 if(promoCode)statements.push(env.DB.prepare('INSERT INTO bx_shipping_expectations(order_id,code,methods) VALUES(?,?,?)').bind(id,promoCode,promoGift.shipping_methods));
 statements.push(env.DB.prepare('INSERT INTO bx_order_finance(order_id,customer_id,gross,promo_code,promo_percent,discount,points_used) VALUES(?,?,?,?,?,?,?)').bind(id,customer?.id||null,total,promoCode,promoPercent,discount,points));
 const freePromo=!!(promoGift?.shipping_methods&&(promoGift.shipping_methods===delivery||(promoGift.shipping_methods==='both'&&['courier','cdek'].includes(delivery))));
 const deliverySettings=await env.DB.prepare('SELECT courier_price,free_from FROM rules_delivery_settings WHERE id=1').first();if(!deliverySettings)return sendJson({error:'Настройки доставки недоступны'},503,cors(req,env));
 const deliveryQuote=rulesShippingQuote(delivery,city,saleTotal-discount,freePromo,deliverySettings,requestedZone);
 statements.push(env.DB.prepare('INSERT INTO rules_delivery_quotes(order_id,method,state,quoted_rub,merchandise_after_discounts) VALUES(?,?,?,?,?)').bind(id,delivery,deliveryQuote.state,deliveryQuote.quotedRub,saleTotal-discount));
 statements.push(env.DB.prepare('INSERT INTO outbox(order_id) VALUES(?)').bind(id));
 try{await env.DB.batch(statements)}catch(e){const existing=await env.DB.prepare('SELECT id,total FROM orders WHERE id=?').bind(id).first();if(existing){const ship=await env.DB.prepare('SELECT free_shipping FROM bx_order_shipping_benefits WHERE order_id=?').bind(id).first();const deliveryQuote=await readRulesQuote(env,id);return sendJson({ok:true,id,duplicate:true,total:existing.total,freeShipping:!!ship?.free_shipping,deliveryQuote},200,cors(req,env))}const detail=String(e?.message||e||'');const reason=detail.includes('promo_login_required')?'Для промокода войдите через Telegram':detail.includes('promo_first_linked_order_only')?'Промокод действует только на первый привязанный заказ':detail.includes('promo_customer_limit')?'Лимит применений промокода для покупателя исчерпан':detail.includes('promo_required_product')?'В корзине нет необходимого товара или количества':'Цена, наличие, акция или баланс изменились. Обновите страницу и попробуйте снова.';return sendJson({error:reason},409,cors(req,env))}
 ctx.waitUntil(notify(env,id).catch(()=>{}));ctx.waitUntil(flushCustomerNotifications(env).catch(()=>{}));return sendJson({ok:true,id,total:saleTotal-discount-points,freeShipping:freePromo,deliveryQuote:{...deliveryQuote,merchandiseAfterDiscounts:saleTotal-discount,provisional:true}},200,cors(req,env));
}
