const PDF_GENERATOR = "/* Offline PDF generation; data must originate from the protected invoice API. */\nwindow.downloadRulesInvoice=async function(invoice){\n if(!window.PDFLib||!window.fontkit)throw Error('\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 PDF.');\n const {PDFDocument,rgb,PDFName,PDFString}=PDFLib,doc=await PDFDocument.create();doc.registerFontkit(fontkit);\n const fontBytes=await fetch(window.RULES_INVOICE_FONT_URL||'assets/fonts/Manrope-400.ttf').then(r=>{if(!r.ok)throw Error('\u0428\u0440\u0438\u0444\u0442 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d');return r.arrayBuffer()});const font=await doc.embedFont(fontBytes,{subset:true});\n const paymentUrl='https://finance.ozon.ru/apps/sbp/ozonbankpay/fa2ea0be-5842-4fc8-b435-d0f46f782d55',ink=rgb(.07,.14,.14),green=rgb(.07,.38,.41),gray=rgb(.35,.40,.40);let page,y;\n function newPage(){page=doc.addPage([595,842]);page.drawRectangle({x:0,y:760,width:595,height:82,color:rgb(.06,.16,.16)});page.drawText('RULES.',{x:36,y:801,size:23,font,color:rgb(1,1,1)});page.drawText('\u0421\u0412\u041e\u0419 \u0412\u041e\u0417\u0414\u0423\u0425. \u0421\u0412\u041e\u0418 \u041f\u0420\u0410\u0412\u0418\u041b\u0410.',{x:36,y:780,size:9,font,color:rgb(.45,.84,.82)});y=735}\n function ensure(h){if(y-h<52)newPage()}\n function text(t,size=10,color=ink){t=String(t??'').replace(/[\\x00-\\x1f\\x7f]/g,' ').replace(/\\s+/g,' ').trim();let line='';for(const word of t.split(' ')){let part=word;while(part){let n=part.length;while(n>1&&font.widthOfTextAtSize((line?line+' ':'')+part.slice(0,n),size)>520)n--;if(line&&font.widthOfTextAtSize(line+' '+part.slice(0,n),size)>520){ensure(size+8);page.drawText(line,{x:36,y,size,font,color});y-=size+7;line='';continue}line+=(line?' ':'')+part.slice(0,n);part=part.slice(n);if(part){ensure(size+8);page.drawText(line,{x:36,y,size,font,color});y-=size+7;line=''}}}if(line){ensure(size+8);page.drawText(line,{x:36,y,size,font,color});y-=size+7}}\n const rub=n=>new Intl.NumberFormat('ru-RU').format(n)+' \u20bd';newPage();text('\u0421\u0427\u0401\u0422 \u041d\u0410 \u041e\u041f\u041b\u0410\u0422\u0423',19,green);text('\u041d\u043e\u043c\u0435\u0440 \u0441\u0447\u0451\u0442\u0430 / \u0437\u0430\u043a\u0430\u0437\u0430: '+invoice.id,10);if(invoice.version)text('\u0412\u0435\u0440\u0441\u0438\u044f \u0441\u0447\u0451\u0442\u0430: '+invoice.version+'  /  \u0432\u044b\u043f\u0443\u0449\u0435\u043d: '+invoice.issuedAt,9,gray);text('\u0414\u0430\u0442\u0430 \u0437\u0430\u043a\u0430\u0437\u0430: '+invoice.createdAt+' UTC   \u2022   \u0420\u0435\u0436\u0438\u043c \u043d\u0430\u043b\u043e\u0433\u043e\u043e\u0431\u043b\u043e\u0436\u0435\u043d\u0438\u044f: \u041d\u041f\u0414',9,gray);y-=10;text('\u041f\u041e\u041b\u0423\u0427\u0410\u0422\u0415\u041b\u042c',11,green);text('\u0420\u044f\u0441\u043e\u0432 \u0410\u043d\u0442\u043e\u043d \u0421\u0435\u0440\u0433\u0435\u0435\u0432\u0438\u0447   \u2022   \u0418\u041d\u041d 773175824431');text('\u0422\u0435\u043b\u0435\u0444\u043e\u043d: +7 (903) 558-22-31   \u2022   E-mail: anton.ryasov@outlook.com');text('\u0411\u0430\u043d\u043a: \u041e\u0437\u043e\u043d \u0411\u0430\u043d\u043a (Ozon)   \u2022   \u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u043e \u0441\u0441\u044b\u043b\u043a\u0435: \u0421\u0411\u041f \u0438\u043b\u0438 \u043a\u0430\u0440\u0442\u0430');y-=9;text('\u041f\u041e\u041a\u0423\u041f\u0410\u0422\u0415\u041b\u042c',11,green);text(invoice.buyer.name+'   \u2022   '+invoice.buyer.phone);if(invoice.buyer.email)text('E-mail: '+invoice.buyer.email);text([invoice.buyer.city,invoice.buyer.address].filter(Boolean).join(', '));y-=8;text('\u0421\u041e\u0421\u0422\u0410\u0412 \u0417\u0410\u041a\u0410\u0417\u0410',11,green);for(const item of invoice.items)text(item.name+'  \u00d7 '+item.qty+'  \u2014  '+rub(item.unitPrice*item.qty));if(invoice.discount)text('\u0421\u043a\u0438\u0434\u043a\u0430 \u043f\u043e \u043f\u0440\u043e\u043c\u043e\u043a\u043e\u0434\u0443: \u2212 '+rub(invoice.discount));if(invoice.points)text('\u041e\u043f\u043b\u0430\u0447\u0435\u043d\u043e \u0431\u0430\u043b\u043b\u0430\u043c\u0438: \u2212 '+rub(invoice.points));text('\u0418\u0442\u043e\u0433\u043e \u0437\u0430 \u0442\u043e\u0432\u0430\u0440\u044b: '+rub(invoice.goodsTotal));text(invoice.deliveryLabel+': '+(invoice.deliveryLabel.startsWith('\u0421\u0414\u042d\u041a')?'\u0432 \u0441\u0447\u0451\u0442 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0430':rub(invoice.delivery)));y-=10;text('\u0418\u0422\u041e\u0413\u041e \u041a \u041e\u041f\u041b\u0410\u0422\u0415: '+rub(invoice.total),16,green);y-=8;text('\u041e\u041f\u041b\u0410\u0422\u0418\u0422\u042c \u0427\u0415\u0420\u0415\u0417 OZON \u0411\u0410\u041d\u041a',11,green);ensure(25);const linkPage=page,linkY=y;text('\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0443 \u043e\u043f\u043b\u0430\u0442\u044b \u043a\u0430\u0440\u0442\u043e\u0439 \u0438\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 \u0421\u0411\u041f',10,green);const annotation=doc.context.register(doc.context.obj({Type:'Annot',Subtype:'Link',Rect:[36,linkY-4,340,linkY+14],Border:[0,0,0],A:{Type:'Action',S:'URI',URI:PDFString.of(paymentUrl)}}));linkPage.node.set(PDFName.of('Annots'),doc.context.obj([annotation]));text('\u041f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0443\u043a\u0430\u0436\u0438\u0442\u0435 \u0441\u0443\u043c\u043c\u0443 '+rub(invoice.total)+' \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0431\u0430\u043d\u043a\u0430.',9,gray);text('\u041e\u043f\u043b\u0430\u0442\u0443 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043f\u0440\u043e\u0434\u0430\u0432\u0435\u0446. \u0421\u0447\u0451\u0442 \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u043e\u043f\u043b\u0430\u0442\u044b \u0438\u043b\u0438 \u0447\u0435\u043a\u043e\u043c \u041d\u041f\u0414.',9,gray);text('\u0421\u0447\u0451\u0442 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043e\u0442\u043e\u0437\u0432\u0430\u043d. \u041f\u0435\u0440\u0435\u0434 \u043e\u043f\u043b\u0430\u0442\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u0447\u0451\u0442 \u0438 \u0441\u0442\u0430\u0442\u0443\u0441 \u0437\u0430\u043a\u0430\u0437\u0430.',9,gray);\n const bytes=await doc.save();const blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='RULES-invoice-'+invoice.id+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);\n};\n";
const MANROPE_FONT = "";
const enc=new TextEncoder();
async function sha(s){return new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(s)))}
function hex(bytes){return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
async function mac(key,text){const k=await crypto.subtle.importKey('raw',enc.encode(key),{name:'HMAC',hash:'SHA-256'},false,['sign']);return hex(new Uint8Array(await crypto.subtle.sign('HMAC',k,enc.encode(text))))}
function equal(a,b){if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}
async function adminAuth(req,env){if(!env.ADMIN_SESSION_SECRET||env.ADMIN_SESSION_SECRET.length<32)return false;const v=(req.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('rules_admin='))?.slice('rules_admin='.length)||'';const parts=v.split('.');if(parts.length!==2||!/^\d{10,13}$/.test(parts[0])||Number(parts[0])<Date.now()||Number(parts[0])>Date.now()+14400000)return false;return equal(await mac(env.ADMIN_SESSION_SECRET,parts[0]),parts[1])}
function mediaUrl(origin,hash){return hash?origin+'/media/'+hash:null}
async function parseProductImage(value){
 if(value===undefined||value===null)return null;
 if(typeof value!=='string'||value.length>600050)throw Error('Изображение слишком большое после сжатия.');
 const match=/^data:(image\/(?:webp|jpeg));base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);if(!match)throw Error('Поддерживаются изображения WebP и JPEG.');
 let raw;try{raw=atob(match[2])}catch{throw Error('Повреждённые данные изображения.')};if(raw.length<12||raw.length>430000)throw Error('Изображение должно занимать не более 430 КБ после сжатия.');
 const isJpeg=raw.charCodeAt(0)===255&&raw.charCodeAt(1)===216&&raw.charCodeAt(2)===255,isWebp=raw.slice(0,4)==='RIFF'&&raw.slice(8,12)==='WEBP';
 if((match[1]==='image/jpeg'&&!isJpeg)||(match[1]==='image/webp'&&!isWebp))throw Error('Формат изображения не совпадает с содержимым.');
 const bytes=Uint8Array.from(raw,x=>x.charCodeAt(0)),hash=hex(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)));return {hash,mime:match[1],base64:match[2]};
}

