 if(!id||!Number.isSafeInteger(line)||line<1||(cost!==null&&(!Number.isSafeInteger(cost)||cost<0||cost>10000000))||!Object.prototype.hasOwnProperty.call(b,'unitCost'))return respond({error:'Проверьте себестоимость'},400);
